create or replace function public.business_can_manage(p_business_id uuid) returns boolean language sql security definer set search_path=public,pg_temp as $$ select exists(select 1 from public.business_members bm where bm.business_id=p_business_id and bm.user_id=auth.uid() and bm.role in ('owner','admin','manager')); $$;
revoke all on function public.business_can_manage(uuid) from public; grant execute on function public.business_can_manage(uuid) to authenticated;
create or replace function public.business_list_campaigns(p_business_id uuid) returns setof public.enterprise_partner_campaigns language sql security definer set search_path=public,pg_temp as $$ select c.* from public.enterprise_partner_campaigns c join public.enterprise_partner_networks n on n.id=c.network_id where n.owner_business_id=p_business_id and public.business_can_manage(p_business_id) order by c.created_at desc; $$;
create or replace function public.business_create_campaign(p_business_id uuid,p_name text,p_campaign_type text default 'engagement',p_goal text default null,p_status text default 'draft') returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ declare v_network uuid; v_id uuid; begin if not public.business_can_manage(p_business_id) then raise exception 'Business management access required'; end if; select id into v_network from public.enterprise_partner_networks where owner_business_id=p_business_id order by created_at limit 1; if v_network is null then insert into public.enterprise_partner_networks(owner_business_id,name,enabled) values(p_business_id,'Kleenest Partner Network',true) returning id into v_network; end if; insert into public.enterprise_partner_campaigns(network_id,name,campaign_type,goal,status) values(v_network,trim(p_name),coalesce(nullif(trim(p_campaign_type),''),'engagement'),p_goal,coalesce(nullif(trim(p_status),''),'draft')) returning id into v_id; return v_id; end; $$;
create or replace function public.business_update_campaign(p_business_id uuid,p_campaign_id uuid,p_name text,p_campaign_type text,p_goal text,p_status text) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ begin if not public.business_can_manage(p_business_id) then raise exception 'Business management access required'; end if; update public.enterprise_partner_campaigns c set name=trim(p_name),campaign_type=coalesce(nullif(trim(p_campaign_type),''),campaign_type),goal=p_goal,status=coalesce(nullif(trim(p_status),''),status),activated_at=case when p_status='active' and status is distinct from 'active' then now() else activated_at end,paused_at=case when p_status='paused' and status is distinct from 'paused' then now() else paused_at end,completed_at=case when p_status='completed' and status is distinct from 'completed' then now() else completed_at end where c.id=p_campaign_id and c.network_id in(select id from public.enterprise_partner_networks where owner_business_id=p_business_id); if not found then raise exception 'Campaign not found'; end if; return p_campaign_id; end; $$;
create or replace function public.business_delete_campaign(p_business_id uuid,p_campaign_id uuid) returns boolean language plpgsql security definer set search_path=public,pg_temp as $$ begin if not public.business_can_manage(p_business_id) then raise exception 'Business management access required'; end if; delete from public.enterprise_partner_campaigns c where c.id=p_campaign_id and c.network_id in(select id from public.enterprise_partner_networks where owner_business_id=p_business_id); if not found then raise exception 'Campaign not found'; end if; return true; end; $$;
create or replace function public.business_list_events(p_business_id uuid) returns setof public.business_events language sql security definer set search_path=public,pg_temp as $$ select e.* from public.business_events e where e.business_id=p_business_id and public.business_can_manage(p_business_id) order by e.event_date nulls last,e.event_time nulls last,e.created_at desc; $$;
create or replace function public.business_create_event(p_business_id uuid,p_location_id uuid,p_title text,p_description text,p_event_date date,p_event_time time) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ declare v_id uuid; begin if not public.business_can_manage(p_business_id) then raise exception 'Business management access required'; end if; if p_location_id is not null and not exists(select 1 from public.locations where id=p_location_id and business_id=p_business_id) then raise exception 'Location does not belong to business'; end if; insert into public.business_events(business_id,location_id,title,description,event_date,event_time) values(p_business_id,p_location_id,trim(p_title),p_description,p_event_date,p_event_time) returning id into v_id; return v_id; end; $$;
create or replace function public.business_update_event(p_business_id uuid,p_event_id uuid,p_location_id uuid,p_title text,p_description text,p_event_date date,p_event_time time) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ begin if not public.business_can_manage(p_business_id) then raise exception 'Business management access required'; end if; if p_location_id is not null and not exists(select 1 from public.locations where id=p_location_id and business_id=p_business_id) then raise exception 'Location does not belong to business'; end if; update public.business_events set location_id=p_location_id,title=trim(p_title),description=p_description,event_date=p_event_date,event_time=p_event_time where id=p_event_id and business_id=p_business_id; if not found then raise exception 'Event not found'; end if; return p_event_id; end; $$;
create or replace function public.business_delete_event(p_business_id uuid,p_event_id uuid) returns boolean language plpgsql security definer set search_path=public,pg_temp as $$ begin if not public.business_can_manage(p_business_id) then raise exception 'Business management access required'; end if; delete from public.business_events where id=p_event_id and business_id=p_business_id; if not found then raise exception 'Event not found'; end if; return true; end; $$;
create or replace function public.business_list_media(p_business_id uuid) returns table(id uuid,location_id uuid,location_name text,storage_path text,caption text,media_type text,mime_type text,size_bytes bigint,width integer,height integer,sort_order integer,created_at timestamptz) language sql security definer set search_path=public,pg_temp as $$ select p.id,p.location_id,l.name,p.storage_path,p.caption,p.media_type,p.mime_type,p.size_bytes,p.width,p.height,p.sort_order,p.created_at from public.location_photos p join public.locations l on l.id=p.location_id where l.business_id=p_business_id and public.business_can_manage(p_business_id) order by p.created_at desc; $$;
create or replace function public.business_create_media(p_business_id uuid,p_location_id uuid,p_storage_path text,p_caption text,p_media_type text default 'photo',p_mime_type text default null,p_size_bytes bigint default null,p_width integer default null,p_height integer default null,p_sort_order integer default 0) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ declare v_id uuid; begin if not public.business_can_manage(p_business_id) then raise exception 'Business management access required'; end if; if not exists(select 1 from public.locations where id=p_location_id and business_id=p_business_id) then raise exception 'Location does not belong to business'; end if; insert into public.location_photos(location_id,user_id,storage_path,caption,media_type,mime_type,size_bytes,width,height,sort_order) values(p_location_id,auth.uid(),p_storage_path,p_caption,coalesce(nullif(trim(p_media_type),''),'photo'),p_mime_type,p_size_bytes,p_width,p_height,p_sort_order) returning id into v_id; return v_id; end; $$;
create or replace function public.business_update_media(p_business_id uuid,p_media_id uuid,p_storage_path text,p_caption text,p_media_type text,p_sort_order integer) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ begin if not public.business_can_manage(p_business_id) then raise exception 'Business management access required'; end if; update public.location_photos p set storage_path=p_storage_path,caption=p_caption,media_type=coalesce(nullif(trim(p_media_type),''),media_type),sort_order=p_sort_order from public.locations l where p.id=p_media_id and l.id=p.location_id and l.business_id=p_business_id; if not found then raise exception 'Media not found'; end if; return p_media_id; end; $$;
drop function if exists public.business_delete_media(uuid,uuid);
create or replace function public.business_delete_media(p_business_id uuid,p_media_id uuid) returns boolean language plpgsql security definer set search_path=public,pg_temp as $$ begin if not public.business_can_manage(p_business_id) then raise exception 'Business management access required'; end if; delete from public.location_photos p using public.locations l where p.id=p_media_id and l.id=p.location_id and l.business_id=p_business_id; if not found then raise exception 'Media not found'; end if; return true; end; $$;
create or replace function public.business_list_partnerships(p_business_id uuid) returns setof public.partner_programs language sql security definer set search_path=public,pg_temp as $$ select p.* from public.partner_programs p where p.business_id=p_business_id and public.business_can_manage(p_business_id) order by p.created_at desc; $$;
create or replace function public.business_create_partnership(p_business_id uuid,p_name text,p_enabled boolean default false,p_preferred_access boolean default false,p_match_discount_bonus numeric default 0,p_custom_perk text default null) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ declare v_id uuid; begin if not public.business_can_manage(p_business_id) then raise exception 'Business management access required'; end if; insert into public.partner_programs(business_id,name,enabled,preferred_access,match_discount_bonus,custom_perk) values(p_business_id,trim(p_name),p_enabled,p_preferred_access,coalesce(p_match_discount_bonus,0),p_custom_perk) returning id into v_id; return v_id; end; $$;
create or replace function public.business_update_partnership(p_business_id uuid,p_partnership_id uuid,p_name text,p_enabled boolean,p_preferred_access boolean,p_match_discount_bonus numeric,p_custom_perk text) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ begin if not public.business_can_manage(p_business_id) then raise exception 'Business management access required'; end if; update public.partner_programs set name=trim(p_name),enabled=p_enabled,preferred_access=p_preferred_access,match_discount_bonus=coalesce(p_match_discount_bonus,0),custom_perk=p_custom_perk where id=p_partnership_id and business_id=p_business_id; if not found then raise exception 'Partnership not found'; end if; return p_partnership_id; end; $$;
create or replace function public.business_delete_partnership(p_business_id uuid,p_partnership_id uuid) returns boolean language plpgsql security definer set search_path=public,pg_temp as $$ begin if not public.business_can_manage(p_business_id) then raise exception 'Business management access required'; end if; if exists(select 1 from public.partner_agreements where partner_program_id=p_partnership_id) then update public.partner_programs set enabled=false where id=p_partnership_id and business_id=p_business_id; else delete from public.partner_programs where id=p_partnership_id and business_id=p_business_id; end if; if not found then raise exception 'Partnership not found'; end if; return true; end; $$;
create or replace function public.get_location_occupancy(p_location_id uuid,p_window_minutes integer default 30) returns table(location_id uuid,current_visitors bigint,stalls integer,urinals integer,sinks integer,changing_tables integer,showers integer,amenity_count bigint,effective_capacity numeric,occupancy_pct numeric,capacity_source text,window_minutes integer) language sql stable security definer set search_path=public,pg_temp as $$ with f as (select coalesce(stalls,0) stalls,coalesce(urinals,0) urinals,coalesce(sinks,0) sinks,coalesce(changing_tables,0) changing_tables,coalesce(showers,0) showers from public.location_fixtures where location_id=p_location_id),a as (select count(*)::bigint amenity_count from public.location_amenities where location_id=p_location_id),v as (select count(distinct user_id)::bigint current_visitors from (select user_id from public.check_ins where location_id=p_location_id and checked_in_at >= now()-make_interval(mins=>greatest(1,least(coalesce(p_window_minutes,30),240))) union select user_id from public.location_visits where location_id=p_location_id and occurred_at >= now()-make_interval(mins=>greatest(1,least(coalesce(p_window_minutes,30),240)))) q),cap as (select *, (stalls+urinals)::numeric primary_capacity,(stalls+urinals+sinks*0.25+changing_tables*0.25+showers*0.25)::numeric effective_capacity from f) select p_location_id,v.current_visitors,cap.stalls,cap.urinals,cap.sinks,cap.changing_tables,cap.showers,a.amenity_count,greatest(1,case when cap.primary_capacity>0 then cap.effective_capacity else greatest(1,a.amenity_count*0.5) end),least(100,round((v.current_visitors::numeric/greatest(1,case when cap.primary_capacity>0 then cap.effective_capacity else greatest(1,a.amenity_count*0.5) end))*100,1)),case when cap.primary_capacity>0 then 'fixtures+amenities' else 'amenities' end,greatest(1,least(coalesce(p_window_minutes,30),240)) from cap cross join a cross join v; $$;
revoke all on function public.business_list_campaigns(uuid) from public; revoke all on function public.business_create_campaign(uuid,text,text,text,text) from public; revoke all on function public.business_update_campaign(uuid,uuid,text,text,text,text) from public; revoke all on function public.business_delete_campaign(uuid,uuid) from public; revoke all on function public.business_list_events(uuid) from public; revoke all on function public.business_create_event(uuid,uuid,text,text,date,time) from public; revoke all on function public.business_update_event(uuid,uuid,uuid,text,text,date,time) from public; revoke all on function public.business_delete_event(uuid,uuid) from public; revoke all on function public.business_list_media(uuid) from public; revoke all on function public.business_create_media(uuid,uuid,text,text,text,text,bigint,integer,integer,integer) from public; revoke all on function public.business_update_media(uuid,uuid,text,text,text,integer) from public; revoke all on function public.business_delete_media(uuid,uuid) from public; revoke all on function public.business_list_partnerships(uuid) from public; revoke all on function public.business_create_partnership(uuid,text,boolean,boolean,numeric,text) from public; revoke all on function public.business_update_partnership(uuid,uuid,text,boolean,boolean,numeric,text) from public; revoke all on function public.business_delete_partnership(uuid,uuid) from public; revoke all on function public.get_location_occupancy(uuid,integer) from public;
grant execute on function public.business_list_campaigns(uuid) to authenticated; grant execute on function public.business_create_campaign(uuid,text,text,text,text) to authenticated; grant execute on function public.business_update_campaign(uuid,uuid,text,text,text,text) to authenticated; grant execute on function public.business_delete_campaign(uuid,uuid) to authenticated; grant execute on function public.business_list_events(uuid) to authenticated; grant execute on function public.business_create_event(uuid,uuid,text,text,date,time) to authenticated; grant execute on function public.business_update_event(uuid,uuid,uuid,text,text,date,time) to authenticated; grant execute on function public.business_delete_event(uuid,uuid) to authenticated; grant execute on function public.business_list_media(uuid) to authenticated; grant execute on function public.business_create_media(uuid,uuid,text,text,text,text,bigint,integer,integer,integer) to authenticated; grant execute on function public.business_update_media(uuid,uuid,text,text,text,integer) to authenticated; grant execute on function public.business_delete_media(uuid,uuid) to authenticated; grant execute on function public.business_list_partnerships(uuid) to authenticated; grant execute on function public.business_create_partnership(uuid,text,boolean,boolean,numeric,text) to authenticated; grant execute on function public.business_update_partnership(uuid,uuid,text,boolean,boolean,numeric,text) to authenticated; grant execute on function public.business_delete_partnership(uuid,uuid) to authenticated; grant execute on function public.get_location_occupancy(uuid,integer) to authenticated;
create index if not exists idx_enterprise_partner_campaigns_network_created on public.enterprise_partner_campaigns(network_id,created_at desc); create index if not exists idx_business_events_business_date on public.business_events(business_id,event_date,event_time); create index if not exists idx_location_photos_location_created on public.location_photos(location_id,created_at desc); create index if not exists idx_partner_programs_business_created on public.partner_programs(business_id,created_at desc); create index if not exists idx_checkins_location_time on public.check_ins(location_id,checked_in_at desc); create index if not exists idx_location_visits_location_time on public.location_visits(location_id,occurred_at desc);
